contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(c).balance == 0);
        bool reverted;
        c.sendTo(address(0), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && address(c).balance == 0);
    }
    receive() external payable {}
}

